<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { api } from '../api.js'
import { auth, notify } from '../state.js'
import '../admin.css'
import GmailSettings from '../components/GmailSettings.vue'
const props=defineProps({title:String,section:String})
const items=ref([]),page=ref(1),pages=ref(1),total=ref(0),search=ref(''),status=ref(''),loading=ref(false),error=ref(''),modal=ref(false),saving=ref(false),current=ref(null),form=ref({}),details=ref(null),report=ref(null),monthlyReports=ref([]),jobSummary=ref(null),reportBusy=ref(false),examOptions=ref([]),examinerOptions=ref([]),defaultExamInstructions=ref(''),timeSteps=ref({}),targetExam=ref(''),criteria=ref([]),criterion=ref({name:'',description:'',max_score:0,weightage:0}),auditItems=ref([]),reportFrom=ref(''),reportTo=ref(''),securityForm=ref({email:'',current_password:'',new_password:'',confirm_password:''}),securityBusy=ref(false)
const configs={
 courses:{endpoint:'/admin/courses',fields:[['code','Course code','text'],['name','Course name','text'],['description','Description','textarea']],columns:['code','name','status','examination_count']},
 examinations:{endpoint:'/admin/examinations',fields:[['course_id','Course','select-course'],['examiner_id','Assigned examiner','select-examiner'],['title','Name','text'],['type','Type','select-type'],['description','Instructions','textarea'],['duration_minutes','Duration (minutes)','number'],['max_marks','Maximum marks','number'],['slot_creation_start','Slot creation opens','datetime-local'],['slot_creation_end','Slot creation closes','datetime-local'],['booking_start','Booking opens','datetime-local'],['booking_end','Booking closes','datetime-local']],columns:['title','course_code','type','examiner_name','status','booking_start','booking_end']},
 examiners:{endpoint:'/admin/examiners',fields:[['full_name','Full name','text'],['email','Email','email'],['department','Department','text'],['password','Initial password (optional)','password']],columns:['full_name','email','department','is_active']},
 students:{endpoint:'/admin/students',fields:[],columns:['full_name','email','program','department','is_active']},
 slots:{endpoint:'/admin/slots',fields:[],columns:['examination','examiner','starts_at','capacity','booked_seats','available_seats','status']},
 bookings:{endpoint:'/admin/bookings',fields:[],columns:['student','examination','starts_at','examiner','status']}}
configs.evaluations={endpoint:'/admin/evaluations',fields:[],columns:['student','examination','status','total_score','submitted_at']}
const config=computed(()=>configs[props.section]), titleCase=s=>s?.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()), fmt=(k,v)=>k.endsWith('_at')||k.endsWith('_start')||k.endsWith('_end')?(v?new Date(v).toLocaleString():'—'):v??'—'
function toLocalDateTimeInput(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return '';const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function setDateTimeNow(key){form.value[key]=toLocalDateTimeInput(new Date().toISOString())}
function shiftDateTime(key,direction){const value=form.value[key]?new Date(form.value[key]):new Date();if(Number.isNaN(value.getTime()))return;value.setMinutes(value.getMinutes()+direction*(Number(timeSteps.value[key])||15));form.value[key]=toLocalDateTimeInput(value.toISOString())}
async function load(){loading.value=true;error.value='';try{if(props.section==='reports'){const q=new URLSearchParams();if(reportFrom.value)q.set('date_from',new Date(`${reportFrom.value}T00:00:00`).toISOString());if(reportTo.value)q.set('date_to',new Date(`${reportTo.value}T23:59:59`).toISOString());report.value=await api.request(`/admin/reports/summary?${q}`);const [history,jobs]=await Promise.all([api.request('/admin/monthly-reports'),api.request('/admin/jobs/summary')]);monthlyReports.value=history.items;jobSummary.value=jobs;return}if(props.section==='settings'){details.value=await api.request('/admin/settings');securityForm.value.email=details.value.profile.email;return}if(props.section==='audit-log'){const r=await api.request(`/admin/audit?page=${page.value}&per_page=20`);auditItems.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;return}if(props.section==='rubrics'){const r=await api.request('/admin/examinations?per_page=100');examOptions.value=r.items;if(!targetExam.value&&r.items.length)targetExam.value=String(r.items[0].id);await loadRubric();return}if(!config.value)return;const q=new URLSearchParams({page:String(page.value),per_page:'15'});if(search.value)q.set('search',search.value);if(status.value)q.set('status',status.value);const r=await api.request(`${config.value.endpoint}?${q}`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;if(props.section==='examinations'){const [courses,examiners,settings]=await Promise.all([api.request('/admin/courses?per_page=100'),api.request('/admin/examiners?per_page=100&status=active'),api.request('/admin/settings')]);examOptions.value=courses.items;examinerOptions.value=examiners.items;defaultExamInstructions.value=settings.settings.default_exam_instructions||''}}catch(e){error.value=e.message}finally{loading.value=false}}
async function updateAdminSecurity(){securityBusy.value=true;try{const result=await api.request('/admin/settings',{method:'PATCH',body:JSON.stringify(securityForm.value)});auth.user=result.profile;securityForm.value={email:result.profile.email,current_password:'',new_password:'',confirm_password:''};notify('Admin email and password settings updated')}catch(e){notify(e.message,'danger')}finally{securityBusy.value=false}}
async function generateMonthlyReport(){reportBusy.value=true;try{const result=await api.request('/admin/monthly-reports',{method:'POST'});notify(result.item.status==='completed'?'Monthly report is ready.':`Report ${result.item.status}.`);await load()}catch(e){notify(e.message,'danger')}finally{reportBusy.value=false}}
async function downloadMonthlyReport(item){try{await api.download(item.download_url,`examination-report-${item.period_start.slice(0,7)}.html`)}catch(e){notify(e.message,'danger')}}
async function loadRubric(){if(targetExam.value)try{criteria.value=(await api.request(`/admin/examinations/${targetExam.value}/rubric`)).items}catch(e){error.value=e.message}}
let timer;watch([search,status],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,250)});watch(()=>props.section,load);watch(page,load);watch(targetExam,loadRubric);onMounted(load)
function openCreate(){current.value=null;form.value={};timeSteps.value={slot_creation_start:15,slot_creation_end:15,booking_start:15,booking_end:15};modal.value=true}function openEdit(x){current.value=x;form.value={...x};timeSteps.value={slot_creation_start:15,slot_creation_end:15,booking_start:15,booking_end:15};for(const k of ['slot_creation_start','slot_creation_end','booking_start','booking_end'])form.value[k]=toLocalDateTimeInput(form.value[k]);modal.value=true}
async function save(){saving.value=true;try{let p=Object.fromEntries(config.value.fields.map(([key])=>[key,form.value[key]]));if(props.section==='examinations'){p.course_id=Number(p.course_id);p.examiner_id=p.examiner_id?Number(p.examiner_id):null;p.duration_minutes=Number(p.duration_minutes);p.max_marks=Number(p.max_marks);for(const k of ['slot_creation_start','slot_creation_end','booking_start','booking_end'])if(p[k])p[k]=new Date(p[k]).toISOString()}if(props.section==='examiners'&&!p.password)delete p.password;const r=await api.request(config.value.endpoint+(current.value?`/${current.value.id}`:''),{method:current.value?'PATCH':'POST',body:JSON.stringify(p)});notify(r.initial_password?`Examiner created. Initial password: ${r.initial_password}`:`${props.title} saved`);modal.value=false;await load()}catch(e){notify(e.message,'danger')}finally{saving.value=false}}
async function toggle(x){try{const path=props.section==='students'?`/admin/students/${x.id}`:`/admin/examiners/${x.id}`;await api.request(path,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});notify('Account status updated');await load()}catch(e){notify(e.message,'danger')}}
async function deleteStudent(x){const message='Permanently delete '+x.full_name+' ('+x.email+')? Their related records and private exports will also be removed. This cannot be undone.';if(!confirm(message))return;try{const r=await api.request('/admin/students/'+x.id,{method:'DELETE'});notify('Student deleted. '+r.bookings_deleted+' bookings and '+r.submissions_deleted+' submissions removed.');await load()}catch(e){notify(e.message,'danger')}}
async function archive(x){if(!confirm(`Archive ${x.code}?`))return;try{await api.request(`/admin/courses/${x.id}`,{method:'PATCH',body:JSON.stringify({status:'archived'})});notify('Course archived');await load()}catch(e){notify(e.message,'danger')}}
async function deleteCourse(x){if(x.examination_count||!confirm(`Permanently remove unused course ${x.code}? This cannot be undone.`))return;try{await api.request(`/admin/courses/${x.id}`,{method:'DELETE'});notify('Course removed');await load()}catch(e){notify(e.message,'danger')}}
async function lifecycle(x,e){try{await api.request(`/admin/examinations/${x.id}/lifecycle`,{method:'POST',body:JSON.stringify({status:e.target.value})});notify('Lifecycle updated');await load()}catch(err){notify(err.message,'danger');e.target.value=x.status}}
async function updateCapacity(x,e){try{await api.request(`/admin/slots/${x.id}`,{method:'PATCH',body:JSON.stringify({capacity:Number(e.target.value)})});notify('Capacity updated');await load()}catch(err){notify(err.message,'danger');e.target.value=x.capacity}}
async function updateBooking(x,e){try{await api.request(`/admin/bookings/${x.id}`,{method:'PATCH',body:JSON.stringify({status:e.target.value})});notify('Booking updated');await load()}catch(err){notify(err.message,'danger');e.target.value=x.status}}
async function reschedule(x){const starts=prompt('Proposed start time (ISO date/time):',x.starts_at);if(!starts)return;const ends=prompt('Proposed end time (ISO date/time):',x.ends_at);if(!ends)return;if(!confirm(`Move slot ${x.id} from ${new Date(x.starts_at).toLocaleString()} to ${new Date(starts).toLocaleString()}? Existing bookings stay attached.`))return;try{await api.request(`/admin/slots/${x.id}/reschedule`,{method:'POST',body:JSON.stringify({starts_at:new Date(starts).toISOString(),ends_at:new Date(ends).toISOString()})});notify('Slot rescheduled');await load()}catch(e){notify(e.message,'danger')}}
async function reassign(x){const id=prompt(`Current examiner: ${x.examiner} (ID ${x.examiner_id}). Enter the new examiner user ID:`);if(!id)return;if(!confirm(`Reassign slot ${x.id} and evaluation assignments from ${x.examiner} to examiner ID ${id}?`))return;try{await api.request(`/admin/slots/${x.id}/reassign`,{method:'POST',body:JSON.stringify({examiner_id:Number(id)})});notify('Slot reassigned');await load()}catch(e){notify(e.message,'danger')}}
async function rescheduleBooking(x){const slotId=prompt(`Current slot ${x.slot_id} · ${x.starts_at}. Enter the target open slot ID for ${x.examination}:`);if(!slotId)return;if(!confirm(`Move booking ${x.id} from slot ${x.slot_id} to slot ${slotId}?`))return;try{await api.request(`/admin/bookings/${x.id}`,{method:'PATCH',body:JSON.stringify({slot_id:Number(slotId)})});notify('Booking rescheduled');details.value=null;await load()}catch(e){notify(e.message,'danger')}}
async function view(x){try{const base={examinations:'examinations',examiners:'examiners',students:'students',slots:'slots',bookings:'bookings'}[props.section];const result=await api.request(`/admin/${base}/${x.id}`);details.value=result.item?{...result.item,...(result.workload?{workload:result.workload}:{}),...(result.evaluation?{evaluation:result.evaluation}:{}),...(result.rubric?{rubric:result.rubric}:{}),...(result.slots?{slots:result.slots}:{}),...(result.bookings?{bookings:result.bookings}:{}),...(result.evaluations?{evaluations:result.evaluations}:{}),...(result.published_results?{published_results:result.published_results}:{})}:result}catch(e){notify(e.message,'danger')}}
async function editCriterion(c){const name=prompt('Criterion name:',c.name);if(name===null)return;const max=prompt('Maximum marks:',c.max_score);if(max===null)return;const weight=prompt('Weightage percent:',c.weightage);if(weight===null)return;try{await api.request(`/admin/rubric/${c.id}`,{method:'PATCH',body:JSON.stringify({name,max_score:Number(max),weightage:Number(weight)})});notify('Criterion updated');await loadRubric()}catch(e){notify(e.message,'danger')}}
async function addCriterion(){try{await api.request(`/admin/examinations/${targetExam.value}/rubric`,{method:'POST',body:JSON.stringify(criterion.value)});criterion.value={name:'',description:'',max_score:0,weightage:0};notify('Criterion added');await loadRubric()}catch(e){notify(e.message,'danger')}}
async function deleteCriterion(c){if(!confirm(`Delete “${c.name}”?`))return;try{await api.request(`/admin/rubric/${c.id}`,{method:'DELETE'});notify('Criterion deleted');await loadRubric()}catch(e){notify(e.message,'danger')}}
async function publishEvaluation(x){if(!confirm(`Publish ${x.student}'s ${x.examination} result? The student will be able to see the scorecard.`))return;try{await api.request(`/admin/evaluations/${x.id}/publish`,{method:'POST'});notify('Result published');await load()}catch(e){notify(e.message,'danger')}}
</script>
<template>
 <div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>{{title}}</h1><p class="muted">Manage {{title.toLowerCase()}} with live portal data.</p></div><button v-if="config?.fields.length" class="btn btn-primary" @click="openCreate">＋ Create {{title.slice(0,-1)}}</button></div>
 <template v-if="section==='reports'"><div v-if="error" class="alert alert-danger">{{error}} <button @click="load">Retry</button></div><div v-else-if="loading" class="loading-state">Loading report data…</div><template v-else-if="report"><div class="stats-grid report-grid"><article v-for="(v,k) in report.totals" :key="k" class="stat-card"><div class="stat-value">{{v}}</div><div class="stat-name">{{titleCase(k)}}</div></article></div><div class="lower-grid"><section class="panel-card"><h3>Examiner workload</h3><table class="table admin-table"><tr v-for="x in report.examiner_workload" :key="x.examiner_id"><td>{{x.name}}</td><td>{{x.slots}} slots</td></tr><tr v-if="!report.examiner_workload.length"><td>No assignments</td></tr></table></section><section class="panel-card"><h3>Examination completion</h3><div v-for="x in report.examination_completion" :key="x.status" class="report-line"><span>{{titleCase(x.status)}}</span><strong>{{x.count}}</strong></div></section><section class="panel-card"><h3>Booking trend</h3><div class="trend-bars"><div v-for="x in report.booking_trend" :key="x.month"><span :style="{height:`${Math.max(8,x.bookings*14)}px`}"></span><small>{{x.month}}</small><b>{{x.bookings}}</b></div><p v-if="!report.booking_trend.length" class="muted">No bookings recorded yet.</p></div></section></div></template>
  <section class="panel-card report-history"><div class="panel-heading"><div><h3>Monthly report history</h3><p>Previous calendar month · timezone configured for scheduled jobs</p></div><button class="btn btn-primary" :disabled="reportBusy" @click="generateMonthlyReport">{{reportBusy?'Queuing…':'Generate previous month'}}</button></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Period</th><th>Status</th><th>Email delivery</th><th>Generated</th><th></th></tr></thead><tbody><tr v-for="item in monthlyReports" :key="item.id"><td>{{item.period_start}} to {{item.period_end}}</td><td>{{titleCase(item.status)}}</td><td>{{titleCase(item.delivery_status)}}</td><td>{{fmt('generated_at',item.generated_at)}}</td><td><button v-if="item.download_url" class="btn btn-sm btn-outline-primary" @click="downloadMonthlyReport(item)">Download HTML</button><span v-else class="muted">No artifact</span></td></tr><tr v-if="!monthlyReports.length"><td colspan="5" class="text-center text-secondary">No monthly reports have been generated.</td></tr></tbody></table></div><div v-if="jobSummary" class="job-summary"><strong>Background jobs</strong><span>Exports · Requested {{jobSummary.exports.requested||0}} · Processing {{jobSummary.exports.processing||0}} · Completed {{jobSummary.exports.completed||0}} · Failed {{jobSummary.exports.failed||0}}</span><span>Reports · Queued {{jobSummary.reports.queued||0}} · Processing {{jobSummary.reports.processing||0}} · Completed {{jobSummary.reports.completed||0}} · Failed {{jobSummary.reports.failed||0}}</span></div></section></template> <template v-else-if="section==='settings'"><div v-if="details?.profile" class="profile-card"><div class="profile-banner"><div class="profile-avatar">{{details.profile.full_name[0]}}</div><div><strong>Administrator profile</strong><span>Application settings</span></div></div><form class="profile-form" @submit.prevent="api.updateProfile({full_name:details.profile.full_name}).then(()=>notify('Profile saved')).catch(e=>notify(e.message,'danger'))"><label>Full name<input v-model="details.profile.full_name"></label><label>Email<input :value="details.profile.email" disabled></label><label>Application name<input :value="details.settings.application_name" disabled></label><button class="btn btn-primary">Save profile</button></form></div><section class="panel-card security-card"><div class="panel-heading"><div><h3>Admin sign-in details</h3><p>Confirm your current password to change your email or password.</p></div></div><form class="security-form" @submit.prevent="updateAdminSecurity"><label>Email address<input v-model="securityForm.email" type="email" autocomplete="username" required></label><label>Current password<input v-model="securityForm.current_password" type="password" autocomplete="current-password" required></label><label>New password <span class="muted">(leave blank to keep current)</span><input v-model="securityForm.new_password" type="password" autocomplete="new-password" minlength="10" maxlength="128" placeholder="At least 10 characters"></label><label>Confirm new password<input v-model="securityForm.confirm_password" type="password" autocomplete="new-password" minlength="10" maxlength="128" :required="Boolean(securityForm.new_password)"></label><button class="btn btn-primary" :disabled="securityBusy">{{securityBusy?'Saving…':'Update sign-in details'}}</button></form></section></template><template v-else-if="section==='rubrics'"><section class="panel-card"><div class="filter-row"><label>Examination<select v-model="targetExam" class="form-select"><option v-for="x in examOptions" :key="x.id" :value="String(x.id)">{{x.title}} · {{x.course_code}}</option></select></label></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Criterion</th><th>Description</th><th>Max marks</th><th>Weightage</th><th></th></tr></thead><tbody><tr v-for="c in criteria" :key="c.id"><td>{{c.name}}</td><td>{{c.description||'—'}}</td><td>{{c.max_score}}</td><td>{{c.weightage}}%</td><td><button class="btn btn-sm btn-light" @click="editCriterion(c)">Edit</button> <button class="btn btn-sm btn-outline-danger" @click="deleteCriterion(c)">Delete</button></td></tr><tr v-if="!criteria.length"><td colspan="5" class="text-center text-secondary">No rubric criteria added.</td></tr></tbody></table></div><p class="rubric-total">{{criteria.reduce((a,c)=>a+Number(c.max_score),0)}} maximum marks · {{criteria.reduce((a,c)=>a+Number(c.weightage),0)}}% weightage</p><form class="rubric-form" @submit.prevent="addCriterion"><input v-model="criterion.name" class="form-control" required placeholder="Criterion name"><input v-model="criterion.description" class="form-control" placeholder="Description"><input v-model.number="criterion.max_score" class="form-control" type="number" min="0.01" step="0.01" required placeholder="Max marks"><input v-model.number="criterion.weightage" class="form-control" type="number" min="0" max="100" step="0.1" required placeholder="Weight %"><button class="btn btn-primary">Add criterion</button></form></section></template>
 <template v-else-if="config"><section class="panel-card records-card"><div class="record-toolbar"><div class="search-control"><span>⌕</span><input v-model="search" placeholder="Search records…"></div><select v-model="status" class="form-select status-filter"><option value="">All statuses</option><option v-if="section==='courses'" value="active">Active</option><option v-if="section==='courses'" value="archived">Archived</option><template v-if="['examiners','students'].includes(section)"><option value="active">Active</option><option value="inactive">Inactive</option></template><option v-if="section==='examinations'" v-for="s in ['draft','slot_creation','booking_open','closed','completed']" :value="s">{{titleCase(s)}}</option><option v-if="section==='bookings'" v-for="s in ['booked','cancelled','completed']" :value="s">{{titleCase(s)}}</option></select><span class="record-count">{{total}} records</span></div><div v-if="error" class="alert alert-danger m-3">{{error}} <button @click="load">Retry</button></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th v-for="k in config.columns" :key="k">{{titleCase(k)}}</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td :colspan="config.columns.length+1" class="text-center py-5">Loading…</td></tr><tr v-else-if="!items.length"><td :colspan="config.columns.length+1" class="text-center py-5 text-secondary">No {{title.toLowerCase()}} found.</td></tr><tr v-for="x in items" v-else :key="x.id"><td v-for="k in config.columns" :key="k"><span v-if="k==='status'||k==='is_active'" class="status-pill" :class="`status-${k==='is_active'?(x[k]?'active':'inactive'):x[k]}`">{{k==='is_active'?(x[k]?'Active':'Inactive'):titleCase(x[k])}}</span><span v-else>{{fmt(k,x[k])}}</span></td><td class="actions-cell"><button v-if="section!=='evaluations'" class="btn btn-sm btn-light" @click="view(x)">View</button><button v-if="['courses','examinations','examiners'].includes(section)" class="btn btn-sm btn-light" @click="openEdit(x)">Edit</button><button v-if="section==='courses'&&x.status==='active'" class="btn btn-sm btn-outline-warning" @click="archive(x)">Archive</button><button v-if="section==='courses'&&x.examination_count===0" class="btn btn-sm btn-outline-danger" @click="deleteCourse(x)">Remove</button><button v-if="['students','examiners'].includes(section)" class="btn btn-sm btn-light" @click="toggle(x)">{{x.is_active?'Deactivate':'Activate'}}</button><button v-if="section='students'" class="btn btn-sm btn-outline-danger" @click="deleteStudent(x)">Delete</button><button v-if="section==='evaluations'&&x.status==='submitted'" class="btn btn-sm btn-primary" @click="publishEvaluation(x)">Publish result</button><select v-if="section==='examinations'" class="form-select form-select-sm lifecycle-select" :value="x.status" @change="lifecycle(x,$event)"><option v-for="s in ['draft','slot_creation','booking_open','closed','completed']" :value="s">{{titleCase(s)}}</option></select><input v-if="section==='slots'" class="form-control form-control-sm capacity-input" type="number" min="1" :value="x.capacity" @change="updateCapacity(x,$event)"><select v-if="section==='bookings'" class="form-select form-select-sm lifecycle-select" :value="x.status" @change="updateBooking(x,$event)"><option v-for="s in ['booked','cancelled','completed']" :value="s">{{titleCase(s)}}</option></select></td></tr></tbody></table></div><div class="pagination-row"><span>{{items.length}} of {{total}}</span><div><button class="btn btn-sm btn-light" :disabled="page<=1" @click="page--">Previous</button><span>Page {{page}} of {{Math.max(1,pages)}}</span><button class="btn btn-sm btn-light" :disabled="page>=pages" @click="page++">Next</button></div></div></section></template>
 <template v-if="section==='audit-log'"><section class="panel-card records-card"><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Record</th><th>Details</th></tr></thead><tbody><tr v-for="a in auditItems" :key="a.id"><td>{{fmt('created_at',a.created_at)}}</td><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.entity_type}}</td><td>{{a.entity_id}}</td><td>{{JSON.stringify(a.metadata)}}</td></tr><tr v-if="!auditItems.length"><td colspan="6" class="text-center">No activity recorded yet.</td></tr></tbody></table></div><div class="pagination-row"><span>{{total}} activity records</span><div><button class="btn btn-sm btn-light" :disabled="page<=1" @click="page--">Previous</button><span>Page {{page}} of {{Math.max(1,pages)}}</span><button class="btn btn-sm btn-light" :disabled="page>=pages" @click="page++">Next</button></div></div></section></template>
 <div v-if="details" class="detail-drawer-backdrop" @click.self="details=null"><section class="detail-drawer"><button class="drawer-close" @click="details=null">×</button><div class="eyebrow">RECORD DETAILS</div><h2>{{details.title||details.full_name||details.student||details.examination||'Details'}}</h2><div v-for="(v,k) in details" :key="k" class="detail-pair"><span>{{titleCase(k)}}</span><strong>{{typeof v==='object'?JSON.stringify(v):fmt(k,v)}}</strong></div></section></div>
 <div v-if="modal" class="modal-backdrop-custom" @click.self="modal=false"><section class="form-modal"><div class="modal-head"><div><div class="eyebrow">{{current?'UPDATE':'NEW'}} {{title.toUpperCase()}}</div><h2>{{current?'Edit':'Create'}} {{title.slice(0,-1)}}</h2></div><button @click="modal=false">×</button></div><form @submit.prevent="save"><label v-for="[k,label,type] in config.fields" :key="k">{{label}}<select v-if="type==='select-course'" v-model="form[k]" class="form-select" required><option value="">Choose course</option><option v-for="x in examOptions" :value="x.id">{{x.code}} · {{x.name}}</option></select><select v-else-if="type==='select-examiner'" v-model="form[k]" class="form-select"><option value="">Unassigned</option><option v-for="x in examinerOptions" :value="x.id">{{x.full_name}} · {{x.department||'No department'}}</option></select><select v-else-if="type==='select-type'" v-model="form[k]" class="form-select"><option v-for="v in ['Viva','Practical','Project Demo','Assessment']">{{v}}</option></select><template v-else-if="type==='datetime-local'"><input v-model="form[k]" class="form-control" type="datetime-local"><div class="time-quick-controls"><button type="button" class="btn btn-sm btn-light" @click="shiftDateTime(k,-1)" :aria-label="`Move ${label} earlier`">−</button><input v-model.number="timeSteps[k]" type="number" min="1" max="10080" aria-label="Custom time adjustment in minutes"><span>min</span><button type="button" class="btn btn-sm btn-light" @click="shiftDateTime(k,1)" :aria-label="`Move ${label} later`">+</button><button type="button" class="btn btn-sm btn-outline-primary" @click="setDateTimeNow(k)">Now</button></div></template><template v-else-if="type==='textarea'"><textarea v-model="form[k]" class="form-control" rows="4" :placeholder="k==='description'?defaultExamInstructions:''"></textarea><div v-if="section==='examinations'&&k==='description'" class="instruction-actions"><button type="button" class="btn btn-sm btn-outline-primary" @click="form[k]=defaultExamInstructions">Use shared default instructions</button><small>Leave blank to use the shared default. Add exam-specific instructions here to override it.</small></div></template><input v-else v-model="form[k]" class="form-control" :type="type" :required="!['password','datetime-local'].includes(type)" :min="type==='number'?'1':undefined"></label><div v-if="section==='examinations'" class="form-hint">Configure dates in your local time. Use the +/- controls to adjust by a custom number of minutes, or choose Now to insert the current time. Dates must follow slot creation start < end ≤ booking start < booking end.</div><div class="modal-actions"><button type="button" class="btn btn-light" @click="modal=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{saving?'Saving…':'Save changes'}}</button></div></form></section></div>
 <section v-if="details && section==='slots'" class="slot-admin-actions panel-card"><strong>Exceptional slot changes</strong><p>Bookings and evaluation assignments remain attached and are updated transactionally.</p><button class="btn btn-sm btn-outline-primary" @click="reschedule(details)">Reschedule slot</button> <button class="btn btn-sm btn-outline-primary" @click="reassign(details)">Reassign examiner</button></section>
 <section v-if="details && section==='bookings'" class="slot-admin-actions panel-card"><strong>Booking rescheduling</strong><p>Choose an open slot for the same examination. The API checks capacity and duplicate active bookings.</p><button class="btn btn-sm btn-outline-primary" :disabled="details.status!=='booked'" @click="rescheduleBooking(details)">Move booking to another slot</button></section>
 <GmailSettings v-if="section==='settings'" />
 </template>







